/** What a seed pass found and did. */
export interface CatalogSeedResult {
  /** Was the catalog empty (and therefore seeded by this pass)? */
  readonly seeded: boolean;
  /** The catalog's item count after the pass (57 right after seeding). */
  readonly itemCount: number;
}

/**
 * Seed the curated catalog IF (and only if) the entertainment graph is
 * empty — the every-environment convergence step of the service boot
 * (idempotent under concurrent cold starts: ON CONFLICT DO NOTHING).
 *
 * NEVER overwrites: an environment whose catalog has any items (operator
 * curations, future tooling) is left exactly as it is — this is a seed,
 * not a sync.
 */
export async function seedCatalogIfEmpty(db: DbClient): Promise<CatalogSeedResult> {
  const existing = await db.query<{ count: string }>(
    "SELECT COUNT(*) AS count FROM entertainment_items",
  );
  const before = Number(existing[0]?.count ?? 0);
  if (before > 0) {
    return { seeded: false, itemCount: before };
  }
  for (const statement of splitStatements(SEED_CATALOG_SQL)) {
    await db.query(statement);
  }
  const after = await db.query<{ count: string }>(
    "SELECT COUNT(*) AS count FROM entertainment_items",
  );
  const itemCount = Number(after[0]?.count ?? 0);
  if (itemCount === 0) {
    // Impossible for the shipped seed (57 inserts, plain statements) — a
    // loud programmer-error guard, never a silent no-op.
    throw new Error(
      "seedCatalogIfEmpty: the seed statements applied but the catalog is still empty " +
        "(the SEED_CATALOG_SQL constant is malformed — this is a programmer error, not a runtime condition)",
    );
  }
  return { seeded: true, itemCount };
}
